/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `tr_carihareket_update` AFTER UPDATE ON `carihareket` FOR EACH ROW BEGIN
    DECLARE v_tl_r DOUBLE DEFAULT 0;
    DECLARE v_tl_gr DOUBLE DEFAULT 0;
    DECLARE v_doviz_r DOUBLE DEFAULT 0;
    DECLARE v_doviz_gr DOUBLE DEFAULT 0;
    DECLARE v_para_old VARCHAR(10);
    DECLARE v_para_new VARCHAR(10);
    
    -- Eski ve yeni şirketin para birimlerini al (PARA zorunlu alan, NULL olmaz)
    SELECT PARA INTO v_para_old FROM sirket WHERE SIRKOD = OLD.SIRKOD LIMIT 1;
    SELECT PARA INTO v_para_new FROM sirket WHERE SIRKOD = NEW.SIRKOD LIMIT 1;
    
    -- Eski değeri çıkar (Eski SIRKOD+FIRKOD+DOVIZTURU kombinasyonundan)
    IF OLD.HESAPTURU > 0 THEN
        SELECT 
            COALESCE(TL_BAKIYE_R * IF(durumR = 'B', -1, 1), 0),
            COALESCE(TL_BAKIYE_GR * IF(durumGR = 'B', -1, 1), 0),
            COALESCE(DOVIZ_BAKIYE_R * IF(durumR = 'B', -1, 1), 0),
            COALESCE(DOVIZ_BAKIYE_GR * IF(durumGR = 'B', -1, 1), 0)
        INTO v_tl_r, v_tl_gr, v_doviz_r, v_doviz_gr
        FROM carihareket_toplam_cache
        WHERE SIRKOD = OLD.SIRKOD 
          AND FIRKOD = OLD.FIRKOD 
          AND DOVIZTURU = OLD.DOVIZTURU;
        
        IF OLD.TGKODU = 1 THEN
            IF OLD.DOVIZTURU = v_para_old THEN
                SET v_tl_r = v_tl_r - (OLD.ALACAK - OLD.BORC);
            ELSE
                SET v_doviz_r = v_doviz_r - (OLD.DOVIZALACAK - OLD.DOVIZBORC);
            END IF;
        ELSEIF OLD.TGKODU = 2 THEN
            IF OLD.DOVIZTURU = v_para_old THEN
                SET v_tl_gr = v_tl_gr - (OLD.ALACAK - OLD.BORC);
            ELSE
                SET v_doviz_gr = v_doviz_gr - (OLD.DOVIZALACAK - OLD.DOVIZBORC);
            END IF;
        END IF;
        
        -- Eski kaydı güncelle veya sil
        IF v_tl_r = 0 AND v_tl_gr = 0 AND v_doviz_r = 0 AND v_doviz_gr = 0 THEN
            DELETE FROM carihareket_toplam_cache 
            WHERE SIRKOD = OLD.SIRKOD 
              AND FIRKOD = OLD.FIRKOD 
              AND DOVIZTURU = OLD.DOVIZTURU;
        ELSE
            UPDATE carihareket_toplam_cache 
            SET TL_BAKIYE_R = ABS(v_tl_r),
                durumR = fn_hesapla_durum(v_tl_r),
                DOVIZ_BAKIYE_R = ABS(v_doviz_r),
                TL_BAKIYE_GR = ABS(v_tl_gr),
                durumGR = fn_hesapla_durum(v_tl_gr),
                DOVIZ_BAKIYE_GR = ABS(v_doviz_gr),
                guncelleme_zamani = NOW()
            WHERE SIRKOD = OLD.SIRKOD 
              AND FIRKOD = OLD.FIRKOD 
              AND DOVIZTURU = OLD.DOVIZTURU;
        END IF;
    END IF;
    
    -- Yeni değeri ekle (Yeni SIRKOD+FIRKOD+DOVIZTURU kombinasyonuna)
    IF NEW.HESAPTURU > 0 THEN
        -- Eğer anahtar değiştiyse (SIRKOD, FIRKOD veya DOVIZTURU) değişkenleri sıfırla
        IF OLD.SIRKOD <> NEW.SIRKOD OR OLD.FIRKOD <> NEW.FIRKOD OR OLD.DOVIZTURU <> NEW.DOVIZTURU THEN
            SET v_tl_r = 0;
            SET v_tl_gr = 0;
            SET v_doviz_r = 0;
            SET v_doviz_gr = 0;
        ELSE
            SELECT 
                COALESCE(TL_BAKIYE_R * IF(durumR = 'B', -1, 1), 0),
                COALESCE(TL_BAKIYE_GR * IF(durumGR = 'B', -1, 1), 0),
                COALESCE(DOVIZ_BAKIYE_R * IF(durumR = 'B', -1, 1), 0),
                COALESCE(DOVIZ_BAKIYE_GR * IF(durumGR = 'B', -1, 1), 0)
            INTO v_tl_r, v_tl_gr, v_doviz_r, v_doviz_gr
            FROM carihareket_toplam_cache
            WHERE SIRKOD = NEW.SIRKOD 
              AND FIRKOD = NEW.FIRKOD 
              AND DOVIZTURU = NEW.DOVIZTURU;
        END IF;
        
        IF NEW.TGKODU = 1 THEN
            IF NEW.DOVIZTURU = v_para_new THEN
                SET v_tl_r = v_tl_r + (NEW.ALACAK - NEW.BORC);
            ELSE
                SET v_doviz_r = v_doviz_r + (NEW.DOVIZALACAK - NEW.DOVIZBORC);
            END IF;
        ELSEIF NEW.TGKODU = 2 THEN
            IF NEW.DOVIZTURU = v_para_new THEN
                SET v_tl_gr = v_tl_gr + (NEW.ALACAK - NEW.BORC);
            ELSE
                SET v_doviz_gr = v_doviz_gr + (NEW.DOVIZALACAK - NEW.DOVIZBORC);
            END IF;
        END IF;
        
        INSERT INTO carihareket_toplam_cache 
            (SIRKOD, FIRKOD, DOVIZTURU, TL_BAKIYE_R, durumR, DOVIZ_BAKIYE_R, 
             TL_BAKIYE_GR, durumGR, DOVIZ_BAKIYE_GR, guncelleme_zamani)
        VALUES 
            (NEW.SIRKOD, NEW.FIRKOD, NEW.DOVIZTURU,
             ABS(v_tl_r), fn_hesapla_durum(v_tl_r), ABS(v_doviz_r),
             ABS(v_tl_gr), fn_hesapla_durum(v_tl_gr), ABS(v_doviz_gr), NOW())
        ON DUPLICATE KEY UPDATE
            TL_BAKIYE_R = ABS(v_tl_r),
            durumR = fn_hesapla_durum(v_tl_r),
            DOVIZ_BAKIYE_R = ABS(v_doviz_r),
            TL_BAKIYE_GR = ABS(v_tl_gr),
            durumGR = fn_hesapla_durum(v_tl_gr),
            DOVIZ_BAKIYE_GR = ABS(v_doviz_gr),
            guncelleme_zamani = NOW();
    END IF;
END */;;
DELIMITER ;
