/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`%`*/ /*!50003 TRIGGER `tr_carihareket_delete` AFTER DELETE ON `carihareket` FOR EACH ROW BEGIN
    DECLARE v_tl_r DOUBLE DEFAULT 0;
    DECLARE v_tl_gr DOUBLE DEFAULT 0;
    DECLARE v_doviz_r DOUBLE DEFAULT 0;
    DECLARE v_doviz_gr DOUBLE DEFAULT 0;
    DECLARE v_para VARCHAR(10);
    
    -- Şirketin para birimini al (PARA zorunlu alan, NULL olmaz)
    SELECT PARA INTO v_para FROM sirket WHERE SIRKOD = OLD.SIRKOD LIMIT 1;
    
    IF OLD.HESAPTURU > 0 THEN
        SELECT 
            COALESCE(TL_BAKIYE_R * IF(durumR = 'B', -1, 1), 0),
            COALESCE(TL_BAKIYE_GR * IF(durumGR = 'B', -1, 1), 0),
            COALESCE(DOVIZ_BAKIYE_R * IF(durumR = 'B', -1, 1), 0),
            COALESCE(DOVIZ_BAKIYE_GR * IF(durumGR = 'B', -1, 1), 0)
        INTO v_tl_r, v_tl_gr, v_doviz_r, v_doviz_gr
        FROM carihareket_toplam_cache
        WHERE SIRKOD = OLD.SIRKOD 
          AND FIRKOD = OLD.FIRKOD 
          AND DOVIZTURU = OLD.DOVIZTURU;
        
        IF OLD.TGKODU = 1 THEN
            IF OLD.DOVIZTURU = v_para THEN
                SET v_tl_r = v_tl_r - (OLD.ALACAK - OLD.BORC);
            ELSE
                SET v_doviz_r = v_doviz_r - (OLD.DOVIZALACAK - OLD.DOVIZBORC);
            END IF;
        ELSEIF OLD.TGKODU = 2 THEN
            IF OLD.DOVIZTURU = v_para THEN
                SET v_tl_gr = v_tl_gr - (OLD.ALACAK - OLD.BORC);
            ELSE
                SET v_doviz_gr = v_doviz_gr - (OLD.DOVIZALACAK - OLD.DOVIZBORC);
            END IF;
        END IF;
        
        IF v_tl_r = 0 AND v_tl_gr = 0 AND v_doviz_r = 0 AND v_doviz_gr = 0 THEN
            DELETE FROM carihareket_toplam_cache 
            WHERE SIRKOD = OLD.SIRKOD 
              AND FIRKOD = OLD.FIRKOD 
              AND DOVIZTURU = OLD.DOVIZTURU;
        ELSE
            UPDATE carihareket_toplam_cache 
            SET TL_BAKIYE_R = ABS(v_tl_r),
                durumR = fn_hesapla_durum(v_tl_r),
                DOVIZ_BAKIYE_R = ABS(v_doviz_r),
                TL_BAKIYE_GR = ABS(v_tl_gr),
                durumGR = fn_hesapla_durum(v_tl_gr),
                DOVIZ_BAKIYE_GR = ABS(v_doviz_gr),
                guncelleme_zamani = NOW()
            WHERE SIRKOD = OLD.SIRKOD 
              AND FIRKOD = OLD.FIRKOD 
              AND DOVIZTURU = OLD.DOVIZTURU;
        END IF;
    END IF;
END */;;
