--
-- Dumping events for database 'erp'
--
/*!50106 SET @save_time_zone= @@TIME_ZONE */ ;
/*!50106 DROP EVENT IF EXISTS `ev_carihareket_cache_kontrol` */;
DELIMITER ;;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;;
/*!50003 SET character_set_client  = utf8mb3 */ ;;
/*!50003 SET character_set_results = utf8mb3 */ ;;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;;
/*!50003 SET sql_mode              = 'NO_AUTO_VALUE_ON_ZERO' */ ;;
/*!50003 SET @saved_time_zone      = @@time_zone */ ;;
/*!50003 SET time_zone             = 'SYSTEM' */ ;;
/*!50106 CREATE*/ /*!50117 DEFINER=`root`@`%`*/ /*!50106 EVENT `ev_carihareket_cache_kontrol` ON SCHEDULE EVERY 1 DAY STARTS '2026-07-07 03:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
    DECLARE v_hata_sayisi INT DEFAULT 0;
    
    CREATE TEMPORARY TABLE temp_cache_hatalar AS
    SELECT 
        c.SIRKOD,
        c.FIRKOD,
        c.DOVIZTURU,
        c.TL_BAKIYE_R,
        c.DOVIZ_BAKIYE_R,
        c.TL_BAKIYE_GR,
        c.DOVIZ_BAKIYE_GR,
        ROUND(gercek.TL_R, 2) AS gercek_tl_r,
        ROUND(gercek.DOVIZ_R, 2) AS gercek_doviz_r,
        ROUND(gercek.TL_GR, 2) AS gercek_tl_gr,
        ROUND(gercek.DOVIZ_GR, 2) AS gercek_doviz_gr,
        ROUND(ABS(c.TL_BAKIYE_R - ABS(gercek.TL_R)), 2) AS tl_r_fark,
        ROUND(ABS(c.DOVIZ_BAKIYE_R - ABS(gercek.DOVIZ_R)), 2) AS doviz_r_fark,
        ROUND(ABS(c.TL_BAKIYE_GR - ABS(gercek.TL_GR)), 2) AS tl_gr_fark,
        ROUND(ABS(c.DOVIZ_BAKIYE_GR - ABS(gercek.DOVIZ_GR)), 2) AS doviz_gr_fark
    FROM carihareket_toplam_cache c
    INNER JOIN (
        SELECT 
            h.SIRKOD,
            h.FIRKOD,
            h.DOVIZTURU,
            SUM(CASE 
                WHEN h.TGKODU = 1 AND h.DOVIZTURU = s.PARA THEN (h.ALACAK - h.BORC)
                ELSE 0 
            END) AS TL_R,
            SUM(CASE 
                WHEN h.TGKODU = 2 AND h.DOVIZTURU = s.PARA THEN (h.ALACAK - h.BORC)
                ELSE 0 
            END) AS TL_GR,
            SUM(CASE 
                WHEN h.TGKODU = 1 AND h.DOVIZTURU != s.PARA THEN (h.DOVIZALACAK - h.DOVIZBORC)
                ELSE 0 
            END) AS DOVIZ_R,
            SUM(CASE 
                WHEN h.TGKODU = 2 AND h.DOVIZTURU != s.PARA THEN (h.DOVIZALACAK - h.DOVIZBORC)
                ELSE 0 
            END) AS DOVIZ_GR
        FROM carihareket h
        INNER JOIN sirket s ON s.SIRKOD = h.SIRKOD
        WHERE h.HESAPTURU > 0
        GROUP BY h.SIRKOD, h.FIRKOD, h.DOVIZTURU
    ) gercek ON gercek.SIRKOD = c.SIRKOD 
             AND gercek.FIRKOD = c.FIRKOD 
             AND gercek.DOVIZTURU = c.DOVIZTURU
    WHERE 
        ROUND(ABS(c.TL_BAKIYE_R - ABS(gercek.TL_R)), 2) > 1
        OR ROUND(ABS(c.DOVIZ_BAKIYE_R - ABS(gercek.DOVIZ_R)), 2) > 1
        OR ROUND(ABS(c.TL_BAKIYE_GR - ABS(gercek.TL_GR)), 2) > 1
        OR ROUND(ABS(c.DOVIZ_BAKIYE_GR - ABS(gercek.DOVIZ_GR)), 2) > 1;
    
    SELECT COUNT(*) INTO v_hata_sayisi FROM temp_cache_hatalar;
    
    IF v_hata_sayisi > 0 THEN
        INSERT INTO carihareket_cache_kontrol_log (kontrol_tarihi, hata_var_mi, hata_sayisi, detay)
        SELECT NOW(), 1, v_hata_sayisi, 
               GROUP_CONCAT(
                   CONCAT('SIRKOD=', SIRKOD, ' FIRKOD=', FIRKOD, ' DOVIZ=', DOVIZTURU, 
                          ' TL_R=', TL_BAKIYE_R, '/', gercek_tl_r,
                          ' DVZ_R=', DOVIZ_BAKIYE_R, '/', gercek_doviz_r,
                          ' TL_GR=', TL_BAKIYE_GR, '/', gercek_tl_gr,
                          ' DVZ_GR=', DOVIZ_BAKIYE_GR, '/', gercek_doviz_gr) 
                   SEPARATOR ' | ')
        FROM temp_cache_hatalar;
    ELSE
        INSERT INTO carihareket_cache_kontrol_log (kontrol_tarihi, hata_var_mi, hata_sayisi)
        VALUES (NOW(), 0, 0);
    END IF;
    
    DROP TEMPORARY TABLE IF EXISTS temp_cache_hatalar;
END */ ;;
