CREATE DEFINER=`root`@`%` FUNCTION `fn_hesapla_durum`(bakiye DOUBLE) RETURNS char(1) CHARSET utf8mb4 COLLATE utf8mb4_general_ci
    NO SQL
    DETERMINISTIC
BEGIN
    IF bakiye > 0 THEN
        RETURN 'A';
    ELSEIF bakiye < 0 THEN
        RETURN 'B';
    ELSE
        RETURN '-';
    END IF;
END ;;
DELIMITER ;
