/*!50003 DROP PROCEDURE IF EXISTS `OptimizeErpTek` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `OptimizeErpTek`()
BEGIN
    DECLARE done INT DEFAULT FALSE;
    DECLARE tbl VARCHAR(64);
    DECLARE frag DECIMAL(10,2);
    
    DECLARE cur CURSOR FOR 
        SELECT table_name, (data_free/(data_length+index_length))*100
        FROM information_schema.tables 
        WHERE table_schema = 'erp' 
        AND engine = 'InnoDB'
        AND (data_free/(data_length+index_length))*100 > 30;
    
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    OPEN cur;
    read_loop: LOOP
        FETCH cur INTO tbl, frag;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        SELECT CONCAT('Optimizing: ', tbl, ' (Fragmentation: ', ROUND(frag,2), '%)') as status;
        
        SET @sql = CONCAT('ALTER TABLE erp.', tbl, 
                          ' ENGINE=InnoDB, ALGORITHM=INPLACE, LOCK=NONE');
        PREPARE stmt FROM @sql;
        EXECUTE stmt;
        DEALLOCATE PREPARE stmt;
        
        DO SLEEP(1); -- Sistem yükünü azaltmak için
    END LOOP;
    CLOSE cur;
    
    SELECT 'Optimization completed!' as result;
END ;;
DELIMITER ;
