PMIKTAR`,0) when 'K' then coalesce(`kg`.`ADET`,0) when 'KS' then coalesce(`kg`.`KSMIKTAR`,0) when 'S' then coalesce(`kg`.`SAPMIKTAR`,0) when 'D1' then coalesce(`kg`.`D1MIKTAR`,0) when 'D2' then coalesce(`kg`.`D2MIKTAR`,0) when 'D3' then coalesce(`kg`.`D3MIKTAR`,0) when 'D4' then coalesce(`kg`.`D4MIKTAR`,0) when 'D5' then coalesce(`kg`.`D5MIKTAR`,0) when 'D6' then coalesce(`kg`.`D6MIKTAR`,0) when 'D7' then coalesce(`kg`.`D7MIKTAR`,0) when 'D8' then coalesce(`kg`.`D8MIKTAR`,0) when 'D9' then coalesce(`kg`.`D9MIKTAR`,0) when 'F' then coalesce(`kg`.`FMIKTAR`,0) when 'V' then coalesce(`kg`.`VMIKTAR`,0) else 0 end)) AS `MIKTAR` from ((select 'PM' AS `source_key` union all select 'K' AS `source_key` union all select 'KS' AS `source_key` union all select 'S' AS `source_key` union all select 'D1' AS `source_key` union all select 'D2' AS `source_key` union all select 'D3' AS `source_key` union all select 'D4' AS `source_key` union all select 'D5' AS `source_key` union all select 'D6' AS `source_key` union all select 'D7' AS `source_key` union all select 'D8' AS `source_key` union all select 'D9' AS `source_key` union all select 'F' AS `source_key` union all select 'V' AS `source_key`) `src` join `kantargirispalet` `kg`) where (((`src`.`source_key` = 'PM') and (`kg`.`PMALKODU` is not null) and (`kg`.`PMALKODU` <> '') and (coalesce(`kg`.`PMIKTAR`,0) > 0)) or ((`src`.`source_key` = 'K') and (`kg`.`KMALKODU` is not null) and (`kg`.`KMALKODU` <> '') and (coalesce(`kg`.`ADET`,0) > 0)) or ((`src`.`source_key` = 'KS') and (`kg`.`KSMALKODU` is not null) and (`kg`.`KSMALKODU` <> '') and (coalesce(`kg`.`KSMIKTAR`,0) > 0)) or ((`src`.`source_key` = 'S') and (`kg`.`SAPMALKODU` is not null) and (`kg`.`SAPMALKODU` <> '') and (coalesce(`kg`.`SAPMIKTAR`,0) > 0)) or ((`src`.`source_key` = 'D1') and (`kg`.`D1MALKODU` is not null) and (`kg`.`D1MALKODU` <> '') and (coalesce(`kg`.`D1MIKTAR`,0) > 0)) or ((`src`.`source_key` = 'D2') and (`kg`.`D2MALKODU` is not null) and (`kg`.`D2MALKODU` <> '') and