here (`sozlesmebahce`.`FISTUR` = 20) group by `sozlesmebahce`.`SIRKOD`,`sozlesmebahce`.`SOZLESMENO`,`sozlesmebahce`.`MALKODU`) `sz` on(((`sz`.`SIRKOD` = `s`.`SIRKOD`) and (`sz`.`SOZLESMENO` = `s`.`SOZLESMENO`) and (`sz`.`MALKODU` = `s`.`MALKODU`)))) left join (select `puantaj_fisleri`.`SIRKOD` AS `SIRKOD`,`puantaj_fisleri`.`SIPARISNO` AS `SIPARISNO`,sum(`puantaj_fisleri`.`MIKTAR`) AS `YEVMIYE_TOPLAM_MIKTAR`,sum(`puantaj_fisleri`.`TUTAR`) AS `YEVMIYE_TOPLAM_TUTAR` from `puantaj_fisleri` where (`puantaj_fisleri`.`SIPARISNO` > 0) group by `puantaj_fisleri`.`SIRKOD`,`puantaj_fisleri`.`SIPARISNO`) `yv` on(((`yv`.`SIRKOD` = `s`.`SIRKOD`) and (`yv`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `sozlesme_bazinda_satis`.`SIRKOD` AS `SIRKOD`,`sozlesme_bazinda_satis`.`SIPARISNO` AS `SIPARISNO`,`sozlesme_bazinda_satis`.`MALKODU` AS `MALKODU`,sum(`sozlesme_bazinda_satis`.`MALKABUL_NET_MIKTAR`) AS `SATIS_NET_MIKTAR`,sum(`sozlesme_bazinda_satis`.`TOTAL_SATIR_TUTARI`) AS `SATIS_TUTARI` from `sozlesme_bazinda_satis` where (`sozlesme_bazinda_satis`.`SIPARISNO` > 0) group by `sozlesme_bazinda_satis`.`SIRKOD`,`sozlesme_bazinda_satis`.`SIPARISNO`,`sozlesme_bazinda_satis`.`MALKODU`) `st` on(((`st`.`SIRKOD` = `s`.`SIRKOD`) and (`st`.`SIPARISNO` = `s`.`FATNO`) and (`st`.`MALKODU` = `s`.`MALKODU`)))) left join `isyeritanimi` `isy` on(((`isy`.`SIRKOD` = `s`.`SIRKOD`) and (`isy`.`KODU` = `s`.`ISYERINO`)))) left join (select `sozlesme_bazinda_paketleme`.`SIRKOD` AS `SIRKOD`,`sozlesme_bazinda_paketleme`.`SIPARISNO` AS `SIPARISNO`,`sozlesme_bazinda_paketleme`.`MALKODU` AS `MALKODU`,sum(`sozlesme_bazinda_paketleme`.`PALET`) AS `PAK_PALET`,sum(`sozlesme_bazinda_paketleme`.`KASA`) AS `PAK_KASA`,sum(`sozlesme_bazinda_paketleme`.`BURUT`) AS `PAK_BURUT`,sum(`sozlesme_bazinda_paketleme`.`NETKG`) AS `PAK_NETKG` from `sozlesme_bazinda_paketleme` where (`sozlesme_bazinda_paketleme`.`SIPARISNO` > 0) group by `sozlesme_bazinda_paketleme`.`SIRKOD`,`sozlesme_bazinda_paketleme`.`SIPARISNO`,`sozlesme_bazinda_paketleme`.`MALKODU`) `p` on(((`p`.`SIRKOD` = `s`.`SIRKOD`) and (`p`.`SIPARISNO` = `s`.`FATNO`) and (`p`.`MALKODU` = `s`.`MALKODU`)))) left join (select `siparis_bazinda_nakliye`.`SIRKOD` AS `SIRKOD`,`siparis_bazinda_nakliye`.`SIPARISNO` AS `SIPARISNO`,sum(`siparis_bazinda_nakliye`.`TOPLAMNAKLIYE`) AS `NAKLIYE_TOPLAM` from `siparis_bazinda_nakliye` where (`siparis_bazinda_nakliye`.`SIPARISNO` > 0) group by `siparis_bazinda_nakliye`.`SIRKOD`,`siparis_bazinda_nakliye`.`SIPARISNO`) `nk` on(((`nk`.`SIRKOD` = `s`.`SIRKOD`) and (`nk`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `n_umemrifis`.`SIRKOD` AS `SIRKOD`,`n_umemrifis`.`SIPARISNO` AS `SIPARISNO`,max(`n_umemrifis`.`REFNO`) AS `BEYAN_NO` from `n_umemrifis` where (`n_umemrifis`.`SIPARISNO` > 0) group by `n_umemrifis`.`SIRKOD`,`n_umemrifis`.`SIPARISNO`) `um` on(((`um`.`SIRKOD` = `s`.`SIRKOD`) and (`um`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `stkfis`.`SIRKOD` AS `SIRKOD`,`stkfis`.`SIPARISNO` AS `SIPARISNO`,max(`stkfis`.`GIBFATURANO`) AS `GIB_FATURANO`,max(`stkfis`.`FATNO`) AS `STKFIS_FATNO` from `stkfis` where ((`stkfis`.`FISTUR` in (20,750)) and (`stkfis`.`SIPARISNO` > 0)) group by `stkfis`.`SIRKOD`,`stkfis`.`SIPARISNO`) `sf` on(((`sf`.`SIRKOD` = `s`.`SIRKOD`) and (`sf`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `stkfisyuk`.`SIRKOD` AS `SIRKOD`,`stkfisyuk`.`SIPARISNO` AS `SIPARISNO`,max(`stkfisyuk`.`FISTAR`) AS `YUKLEME_TARIHI` from `stkfisyuk` where (`stkfisyuk`.`SIPARISNO` > 0) group by `stkfisyuk`.`SIRKOD`,`stkfisyuk`.`SIPARISNO`) `yk` on(((`yk`.`SIRKOD` = `s`.`SIRKOD`) and (`yk`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `siparis_havale`.`SIRKOD` AS `SIRKOD`,`siparis_havale`.`SIPARISNO` AS `SIPARISNO`,sum(`siparis_havale`.`TUTAR`) AS `HAVALE_TOPLAM_TUTAR`,sum(`siparis_havale`.`DOVIZTUTAR`) AS `HAVALE_TOPLAM_DOVIZ` from `siparis_havale` where (`siparis_havale`.`SIPARISNO` > 0) group by `siparis_havale`.`SIRKOD`,`siparis_havale`.`SIPARISNO`) `hv` on(((`hv`.`SIRKOD` = `s`.`SIRKOD`) and (`hv`.`SIP