/*!50001 VIEW `t_mustahsil_iskarta` AS select `p`.`SIRKOD` AS `SIRKOD`,`p`.`ANADEPOKODU` AS `ANADEPOKODU`,`p`.`GIRISTARIHI` AS `TARIH`,`p`.`MALKODU` AS `MALKODU`,`p`.`MALADI` AS `MALADI`,`p`.`UFIRKOD` AS `UFIRKOD`,`p`.`UFIRMAADI` AS `UFIRMAADI`,coalesce(`d`.`DOKUM_PALET`,0) AS `DOKUM_PALET`,coalesce(`d`.`DOKUM_KASA`,0) AS `DOKUM_KASA`,coalesce(`d`.`DOKUM_BURUT`,0) AS `DOKUM_BURUT`,coalesce(`d`.`DOKUM_DARA`,0) AS `DOKUM_DARA`,coalesce(`d`.`DOKUM_NET`,0) AS `DOKUM_NET`,sum(`p`.`PMIKTAR`) AS `PAKET_PALET`,sum(`p`.`ADET`) AS `PAKET_KASA`,sum(`p`.`BURUT`) AS `PAKET_BURUT`,sum(`p`.`DARA`) AS `PAKET_DARA`,coalesce(sum((case when (`p`.`KALITE` = '1.KALİTE') then `p`.`NET` end)),0) AS `BIRINCI_KALITE_NET`,coalesce(sum((case when (`p`.`KALITE` <> '1.KALİTE') then `p`.`NET` end)),0) AS `ISKARTA_PAKET_NET`,(case when (coalesce(`d`.`DOKUM_NET`,0) > 0) then round(((coalesce(sum((case when (`p`.`KALITE` <> '1.KALİTE') then `p`.`NET` end)),0) / `d`.`DOKUM_NET`) * 100),2) else 0 end) AS `ISKARTA_ORAN`,sum(`p`.`NET`) AS `PAKET_NET`,(coalesce(`d`.`DOKUM_NET`,0) - sum(`p`.`NET`)) AS `FARK` from (`v_paket_birlestir` `p` left join `t_dokum_ozet` `d` on(((`d`.`SIRKOD` = `p`.`SIRKOD`) and (`d`.`ANADEPOKODU` = `p`.`ANADEPOKODU`) and (`d`.`TARIH` = `p`.`GIRISTARIHI`) and (`d`.`MALKODU` = `p`.`MALKODU`) and (`d`.`UFIRKOD` = `p`.`UFIRKOD`)))) where ((`p`.`FISTUR` = 20) and (`p`.`KALITE` is not null) and (`p`.`KALITE` <> '')) group by `p`.`SIRKOD`,`p`.`ANADEPOKODU`,`p`.`GIRISTARIHI`,`p`.`MALKODU`,`p`.`MALADI`,`p`.`UFIRKOD`,`p`.`UFIRMAADI` union all select `d`.`SIRKOD` AS `SIRKOD`,`d`.`ANADEPOKODU` AS `ANADEPOKODU`,`d`.`TARIH` AS `TARIH`,`d`.`MALKODU` AS `MALKODU`,`d`.`MALADI` AS `MALADI`,`d`.`UFIRKOD` AS `UFIRKOD`,`d`.`UFIRMAADI` AS `UFIRMAADI`,`d`.`DOKUM_PALET` AS `DOKUM_PALET`,`d`.`DOKUM_KASA` AS `DOKUM_KASA`,`d`.`DOKUM_BURUT` AS `DOKUM_BURUT`,`d`.`DOKUM_DARA` AS `DOKUM_DARA`,`d`.`DOKUM_NET` AS `DOKUM_NET`,0 AS `PAKET_PALET`,0 AS `PAKET_KASA`,0 AS `PAKET_BURUT`,0 AS `PAKET_DARA`,0 AS `BIRINCI