/*!50001 VIEW `v_mal_kar_zarar` AS select `al`.`SIRKOD` AS `SIRKOD`,`al`.`FISNO` AS `ALIS_FISNO`,`sa`.`FISNO` AS `SATIS_FISNO`,`al`.`FISTAR` AS `YUKLEME_TARIHI`,`af`.`DOVIZTURU` AS `ALIS_DOVIZTURU`,`af`.`DOVIZKUR` AS `ALIS_DOVIZKUR`,`sf`.`DOVIZTURU` AS `SATIS_DOVIZTURU`,`sf`.`DOVIZKUR` AS `SATIS_DOVIZKUR`,`af`.`GIBFATURANO` AS `FA_INVOICE_NO`,`af`.`IRSTAR` AS `IRSTAR`,`al`.`TGKODU` AS `TGKODU`,`af`.`PLAKA` AS `PLAKA`,`af`.`SIPARISNO` AS `ORDER_NO`,`af`.`POZNO` AS `LOT`,`af`.`SOFOR_ADI` AS `SOFOR`,`af`.`GUMRUKADI` AS `GUMRUK`,`af`.`KONTEYNER_NO` AS `KONTEYNER`,`af`.`BEYANNAME_NO` AS `BEYANNAME`,`al`.`FIRKOD` AS `TEDARIKCI_FIRKOD`,`al`.`FIRMAADI` AS `TEDARIKCI`,`sa`.`FIRKOD` AS `MUSTERI_FIRKOD`,`sa`.`FIRMAADI` AS `MUSTERI`,`al`.`MALKODU` AS `MALKODU`,`al`.`MALADI` AS `MALADI`,`st`.`GRUPKODU` AS `GRUPKODU`,`g`.`ADI` AS `GRUPADI`,`st`.`GRUPKODU1` AS `GRUPKODU1`,`ag`.`ADI` AS `ALT_GRUPADI`,`al`.`BIRIMI` AS `BIRIMI`,`al`.`KG` AS `ALIS_KG`,`al`.`PALET` AS `ALIS_PALET`,`al`.`KUTU` AS `ALIS_KUTU`,`al`.`ALIS_TUTARI` AS `ALIS_TUTARI`,`al`.`ALIS_TOPLAMSATIRTUTARI` AS `ALIS_TOPLAMSATIRTUTARI`,ifnull(`hz`.`FIS_HIZMET_TOPLAM`,0) AS `FIS_HIZMET_TOPLAM`,ifnull(((`hz`.`FIS_HIZMET_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0) AS `HIZMET`,ifnull(`yy`.`FIS_YEVMIYE_TOPLAM`,0) AS `FIS_YEVMIYE_TOPLAM`,ifnull(((`yy`.`FIS_YEVMIYE_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0) AS `YEVMIYE`,((`al`.`ALIS_TUTARI` + ifnull(((`hz`.`FIS_HIZMET_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0)) + ifnull(((`yy`.`FIS_YEVMIYE_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0)) AS `MALIYET_TOPLAM`,`sa`.`SATIS_KG` AS `SATIS_KG`,`sa`.`SATIS_PALET` AS `SATIS_PALET`,`sa`.`SATIS_KUTU` AS `SATIS_KUTU`,`sa`.`SATIS_TUTARI` AS `SATIS_TUTARI`,`sa`.`SATIS_TOPLAMSATIRTUTARI` AS `SATIS_TOPLAMSATIRTUTARI`,(`al`.`KG` - ifnull(`sa`.`SATIS_KG`,0)) AS `KALAN_KG`,(`al`.`KUTU` - ifnull(`sa`.`SATIS_KUTU`,0)) AS `KALAN_KUTU`,(`al`.`PALET` - ifnull(`sa`.`SATIS_PALET`,0)) AS `KALAN_PALET`,(ifnull(`sa`.`SATIS_KG`,0) - `al`.`KG`) AS `ASIM_KG`,(case when ((`sa`.`SATIS_KG` is null) or (`sa`.`SATIS_KG` = 0)) then NULL else (`sa`.`SATIS_TUTARI` - ((`al`.`ALIS_TUTARI` + ifnull(((`hz`.`FIS_HIZMET_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0)) + ifnull(((`yy`.`FIS_YEVMIYE_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0))) end) AS `SONUC`,(case when (`al`.`ALIS_TUTARI` = 0) then 'MALIYET_GIRILMEMIS' when ((`sa`.`SATIS_KG` is null) or (`sa`.`SATIS_KG` = 0)) then 'SATILMADI' when ((`sa`.`SATIS_TUTARI` - ((`al`.`ALIS_TUTARI` + ifnull(((`hz`.`FIS_HIZMET_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0)) + ifnull(((`yy`.`FIS_YEVMIYE_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0))) > 0) then 'KAR' when ((`sa`.`SATIS_TUTARI` - ((`al`.`ALIS_TUTARI` + ifnull(((`hz`.`FIS_HIZMET_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0)) + ifnull(((`yy`.`FIS_YEVMIYE_TOPLAM` * `al`.`KG`) / nullif(`kg`.`FIS_TOPLAM_KG`,0)),0))) < 0) then 'ZARAR' else 'BASABAS' end) AS `SONUC_DURUMU` from ((((((((((select `d`.`SIRKOD` AS `SIRKOD`,`d`.`FISNO` AS `FISNO`,`d`.`FISTAR` AS `FISTAR`,`d`.`TGKODU` AS `TGKODU`,`d`.`FIRKOD` AS `FIRKOD`,`d`.`FIRMAADI` AS `FIRMAADI`,`d`.`MALKODU` AS `MALKODU`,`d`.`MALADI` AS `MALADI`,`d`.`BIRIMI` AS `BIRIMI`,sum(`d`.`MIKTAR`) AS `KG`,sum(`d`.`PALET`) AS `PALET`,sum(`d`.`KASA`) AS `KUTU`,sum(`d`.`DOVIZTUTAR`) AS `ALIS_TUTARI`,sum(`d`.`TOPLAMSATIRTUTARI`) AS `ALIS_TOPLAMSATIRTUTARI` from `stkdet` `d` where (`d`.`FISTUR` = 10) group by `d`.`SIRKOD`,`d`.`FISNO`,`d`.`FISTAR`,`d`.`TGKODU`,`d`.`FIRKOD`,`d`.`FIRMAADI`,`d`.`MALKODU`,`d`.`MALADI`,`d`.`BIRIMI`) `al` left join (select `stkdet`.`SIRKOD` AS `SIRKOD`,`stkdet`.`FISNO` AS `FISNO`,sum(`stkdet`.`MIKTAR`) AS `FIS_TOPLAM_KG` from `stkdet` where (`stkdet`.`FISTUR` = 10) group by `stkdet`.`SIRKOD`,`stkdet`.`FISNO`) `kg` on(((`kg`.`SIRKOD` = `al`.`SIRKOD`) and (`kg`.`FISNO` = `al`.`FISNO`)))) left join (select `stkdet`.`SIRKOD` AS `SIRKOD`,`stkdet`.`SEVK_FISNO` AS `SEVK_FISNO`,sum(`stkdet`.`DOVIZTUTAR`) AS `FIS_HIZMET_TOPLAM` from `stkdet` where (`stkdet`.`FISTUR` = 110) group by `stkdet`.`SIRKOD`,`stkdet`.`SEVK_FISNO`) `hz` on(((`hz`.`SIRKOD` = `al`.`SIRKOD`) and (`hz`.`SEVK_FISNO` = `al`.`FISNO`)))) left join (select `stkdet`.`SIRKOD` AS `SIRKOD`,`stkdet`.`SEVK_FISNO` AS `SEVK_FISNO`,sum(`stkdet`.`DOVIZTUTAR`) AS `FIS_YEVMIYE_TOPLAM` from `stkdet` where (`stkdet`.`FISTUR` in (300,350)) group by `stkdet`.`SIRKOD`,`stkdet`.`SEVK_FISNO`) `yy` on(((`yy`.`SIRKOD` = `al`.`SIRKOD`) and (`yy`.`SEVK_FISNO` = `al`.`FISNO`)))) left join (select `d`.`SIRKOD` AS `SIRKOD`,`d`.`SEVK_FISNO` AS `SEVK_FISNO`,`d`.`MALKODU` AS `MALKODU`,`d`.`TGKODU` AS `TGKODU`,`d`.`FIRKOD` AS `FIRKOD`,`d`.`FIRMAADI` AS `FIRMAADI`,sum(`d`.`MIKTAR`) AS `SATIS_KG`,sum(`d`.`KASA`) AS `SATIS_KUTU`,sum(`d`.`PALET`) AS `SATIS_PALET`,sum(`d`.`TUTAR`) AS `SATIS_TUTARI`,sum(`d`.`TOPLAMSATIRTUTARI`) AS `SATIS_TOPLAMSATIRTUTARI`,max(`d`.`FISNO`) AS `FISNO`,max(`d`.`FISTAR`) AS `FISTAR` from (select distinct `s`.`SIRKOD` AS `SIRKOD`,`s`.`SEVK_FISNO` AS `SEVK_FISNO`,`s`.`MALKODU` AS `MALKODU`,`s`.`TGKODU` AS `TGKODU`,`s`.`FIRKOD` AS `FIRKOD`,`s`.`FIRMAADI` AS `FIRMAADI`,`s`.`FISNO` AS `FISNO`,`s`.`FISTAR` AS `FISTAR`,`s`.`MIKTAR` AS `MIKTAR`,`s`.`KASA` AS `KASA`,`s`.`PALET` AS `PALET`,`s`.`TUTAR` AS `TUTAR`,`s`.`TOPLAMSATIRTUTARI` AS `TOPLAMSATIRTUTARI` from `stkdet` `s` where (`s`.`FISTUR` = 20)) `d` group by `d`.`SIRKOD`,`d`.`SEVK_FISNO`,`d`.`MALKODU`,`d`.`TGKODU`,`d`.`FIRKOD`,`d`.`FIRMAADI`) `sa` on(((`sa`.`SIRKOD` = `al`.`SIRKOD`) and (`sa`.`SEVK_FISNO` = `al`.`FISNO`) and (`sa`.`MALKODU` = `al`.`MALKODU`) and (`sa`.`TGKODU` = `al`.`TGKODU`)))) left join `stkfis` `af` on(((`af`.`SIRKOD` = `al`.`SIRKOD`) and (`af`.`FISNO` = `al`.`FISNO`)))) left join `stok` `st` on(((`st`.`SIRKOD` = `al`.`SIRKOD`) and (`st`.`KODU` = `al`.`MALKODU`)))) left join `grup` `g` on(((`g`.`SIRKOD` = `st`.`SIRKOD`) and (`g`.`KODU` = `st`.`GRUPKODU`)))) left join `altgrup` `ag` on(((`ag`.`SIRKOD` = `st`.`SIRKOD`) and (`ag`.`KODU` = `st`.`GRUPKODU1`)))) left join `stkfis` `sf` on(((`sf`.`SIRKOD` = `sa`.`SIRKOD`) and (`sf`.`FISNO` = `sa`.`FISNO`)))) */;
