alim` where (`sozlesme_bazinda_alim`.`SIPARISNO` > 0) group by `sozlesme_bazinda_alim`.`SIRKOD`,`sozlesme_bazinda_alim`.`SIPARISNO`,`sozlesme_bazinda_alim`.`MALKODU`) `p` on(((`p`.`SIRKOD` = `s`.`SIRKOD`) and (`p`.`SIPARISNO` = `s`.`FATNO`) and (`p`.`MALKODU` = `s`.`MALKODU`)))) left join (select `alim_siparis_bazinda_nakliye`.`SIRKOD` AS `SIRKOD`,`alim_siparis_bazinda_nakliye`.`SIPARISNO` AS `SIPARISNO`,sum(`alim_siparis_bazinda_nakliye`.`TOPLAMNAKLIYE`) AS `NAKLIYE_TOPLAM` from `alim_siparis_bazinda_nakliye` where (`alim_siparis_bazinda_nakliye`.`SIPARISNO` > 0) group by `alim_siparis_bazinda_nakliye`.`SIRKOD`,`alim_siparis_bazinda_nakliye`.`SIPARISNO`) `nk` on(((`nk`.`SIRKOD` = `s`.`SIRKOD`) and (`nk`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `n_umemrifis`.`SIRKOD` AS `SIRKOD`,`n_umemrifis`.`SIPARISNO` AS `SIPARISNO`,max(`n_umemrifis`.`REFNO`) AS `BEYAN_NO` from `n_umemrifis` where (`n_umemrifis`.`SIPARISNO` > 0) group by `n_umemrifis`.`SIRKOD`,`n_umemrifis`.`SIPARISNO`) `um` on(((`um`.`SIRKOD` = `s`.`SIRKOD`) and (`um`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `stkfis`.`SIRKOD` AS `SIRKOD`,`stkfis`.`SIPARISNO` AS `SIPARISNO`,max(`stkfis`.`GIBFATURANO`) AS `GIB_FATURANO`,max(`stkfis`.`FATNO`) AS `STKFIS_FATNO` from `stkfis` where ((`stkfis`.`FISTUR` in (10,224)) and (`stkfis`.`SIPARISNO` > 0)) group by `stkfis`.`SIRKOD`,`stkfis`.`SIPARISNO`) `sf` on(((`sf`.`SIRKOD` = `s`.`SIRKOD`) and (`sf`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `stkfisyuk`.`SIRKOD` AS `SIRKOD`,`stkfisyuk`.`SIPARISNO` AS `SIPARISNO`,max(`stkfisyuk`.`FISTAR`) AS `YUKLEME_TARIHI` from `stkfisyuk` where (`stkfisyuk`.`SIPARISNO` > 0) group by `stkfisyuk`.`SIRKOD`,`stkfisyuk`.`SIPARISNO`) `yk` on(((`yk`.`SIRKOD` = `s`.`SIRKOD`) and (`yk`.`SIPARISNO` = `s`.`FATNO`)))) left join (select `alim_siparis_havale`.`SIRKOD` AS `SIRKOD`,`alim_siparis_havale`.`SIPARISNO` AS `SIPARISNO`,sum(`alim_siparis_havale`.`TUTAR`) AS `HAVALE_TOPLAM_TUTAR`,sum(`alim_siparis_havale`.`DOVIZTUTAR`) AS `HAV